def P(num,h,fig,tier,grant,inv,title,teaches,figs,status="Expired",**k):
    d=dict(num=num,hash=h,fig=fig,tier=tier,grant=grant,inv=inv,title=title,teaches=teaches,figs=figs,status=status); d.update(k); return d
INTRO = "<p>Stoves were one of the most-patented household goods of the 1800s. These patents show how to control a fire's air supply, keep heat in the room instead of up the chimney, cook and heat water with the same fire, and cook with stored heat alone. Tiers A and B are within reach of a home workshop. Tier C shows the factory-made items behind modern fire-lighting, firewood and fire protection, so you know what they are and how they work. Read with the stove, chimney and carbon-monoxide chapters of this guide.</p>"
UNPATENTED = ["<b>Benjamin Franklin's</b> 'Pennsylvania fireplace' stove (1740s) &mdash; Franklin declined a patent so anyone could build it.",
 "<b>Count Rumford's</b> shallow, angled-back fireplace (1790s), which throws far more heat into the room, was published freely rather than patented."]
PATENTS = [
P("US930204","5f/47/db/9e2a593f0719ba/US930204.pdf","a3/06/e3/5453a4aacfa46d/US930204-drawings-page-1.png","A","1909-08-03","George A. Marsh &amp; Hiram H. Thompson","Fireless cooker",
  "A fireless (retained-heat) cooker: food brought to the boil is shut in a receptacle with non-conducting walls of felt, sawdust or similar packing and finishes cooking on its own stored heat &mdash; the 'hay box' that saves most of the fuel for beans, grains and stews.","Section through the insulated box, packing and cooking well"),
P("US1298762","e6/91/2a/dd62a837dd427e/US1298762.pdf","2a/cf/2c/3e3417e71c9d0f/US1298762-drawings-page-1.png","A","1919-04-01","James S. Milligan","Camp-stove",
  "A very cheap, simple folding camp stove: a small sheet-metal fire box and grate that confines the fire under the pot.","Stove assembled and folded"),
P("US393242","c3/6d/5f/39a38ee5e0047c/US393242.pdf","24/37/a5/a846bb546f9929/US393242-drawings-page-1.png","A","1888-11-20","Solomon Kepner","Stove-pipe damper",
  "A damper for a stovepipe made from a pipe section with openings on opposite sides and a turning plate, so the draft &mdash; and therefore the burn rate &mdash; can be throttled. Never close a damper fully while a fire is burning (carbon monoxide).","Pipe section with damper plate and handle"),
P("USRE48","7a/ab/ab/eea4163b97ba4c/USRE48.pdf","81/af/03/228086e54e8a83/USRE48-drawings-page-1.png","B","1842-11-12","Isaac Orr","Improvement in air-tight stoves (reissue of 1836 patent)",
  "The original 'air-tight stove': a closed iron box with the door set high, leaving an air chamber above the fuel, and a controlled air inlet, so wood burns slowly and evenly for hours instead of roaring away. The ancestor of every modern controlled-combustion wood stove.","The single sheet: stove body, high door and air chamber"),
P("US900384","d2/e1/90/5caf058c8d5837/US900384.pdf","52/f0/de/61b03f792987f3/US900384-drawings-page-1.png","B","1908-10-06","George G. Kaiser","Wood-burning stove",
  "A wood-burning heating stove for dwellings, showing fire box, grate, flue passages and air control arranged to get more heat from each load of wood.","Sheet 1: vertical section through fire box and flues"),
P("US566732","a1/bc/e3/d73d9361beaa20/US566732.pdf","43/65/dd/a3be027e411372/US566732-drawings-page-1.png","B","1896-09-01","Wella Percy Anderson","Open-fireplace heater",
  "A heater that fits an open fireplace and burns coal or wood, with a built-in oven that can bake, warm food or act as a hot-air chamber to heat the room &mdash; turns a wasteful fireplace into a useful stove.","Front and sectional views showing oven and hot-air passages"),
P("US896591","5b/a7/c8/32236f465cdbb4/US896591.pdf","1b/b1/9e/9717d8a5d9c95c/US896591-drawings-page-1.png","B","1908-08-18","Edward Senn","Cooking-stove",
  "A cooking stove with a large water heater beside the baking oven, heated by the same combustion gases, so one fire cooks, bakes and makes hot water.","Sheet 1: plan and section showing oven, water heater and flue dampers"),
P("US837017","49/87/82/b583039be28a23/US837017.pdf","pdf:1","C","1906-11-27","Carl Auer von Welsbach","Pyrophoric alloy",
  "A cerium-iron spark metal, the kind of alloy a ferro rod is made of. Welsbach found that pure cerium does not spark, but cerium alloyed with iron throws sparks when scraped with a file, with the strongest effect at about 30 per cent iron. Making the alloy needs refined rare-earth metal, so this is factory work; stock up on ferro rods and lighter flints instead.","The single text page: the cerium-iron finding and the claims (no drawings)"),
P("US781700","ca/21/b3/e61d4bf769fa32/US781700.pdf","d6/3d/ec/d1d1ab24e690be/US781700-drawings-page-1.png","C","1905-02-07","George O. Walker","Drag-saw machine",
  "An engine-powered drag saw for bucking felled logs into stove-length blocks. The saw sits on a wheeled truck, and a cable loop from the engine's drum drives it through sheaves. The truck rolls along the log from cut to cut while the engine stays put, saving most of the labor of cutting firewood by hand.","Fig. 1 plan of engine, cable and truck along the log; Figs. 3-4 the truck and sheave layout"),
P("US141062","81/19/af/d2f4026ce5314b/US141062.pdf","0f/40/22/9d1bb9a1f3618a/US141062-drawings-page-2.png","C","1873-07-22","Hiram S. Maxim","Improvement in fire-extinguishers",
  "An early automatic fire-detection and sprinkler system for large buildings and ships. Pipes run to each room and end in nozzles with caps that melt in the heat of a fire. When a cap opens, the pressure in the pipes drops, which starts a generator that makes carbonic-acid gas (CO2) from chips of carbonate of lime and dilute acid, sends gas and water to that spot, and can sound an alarm.","Fig. 1 section through the generator and gas-holder; Fig. 2 the system piped through a house"),
P("US235756","28/63/79/23ebcd2526e821/US235756.pdf","92/b7/24/a982395ece4def/US235756-drawings-page-1.png","A","1880-12-21","John T. Elliott","Fire-kindler",
  "A cheap fire-starter: a lump of solid rosin (or something like it) packed inside absorbent fibrous material such as sawdust. As the rosin melts, the sawdust draws it to the outside by capillary action, like a wick. The flame then lasts long enough, and burns hot enough, to light wood or coal without wasting the rosin. Read with 1.2 Tinder, kindling and fuel.","Fig. 1 the kindler; Fig. 2 section showing the rosin core")
]
